import{_ as a,o as t,c as o,aa as n}from"./chunks/framework.D7Mdgkg-.js";const u=JSON.parse(`{"title":"Create Your First Application","description":"The planned Feluqa getting-started path: choose an application, prepare the environment, create a first CLI command, and build a useful weather watcher.","frontmatter":{"sidebarTitle":"First App","icon":"square-terminal","title":"Create Your First Application","description":"The planned Feluqa getting-started path: choose an application, prepare the environment, create a first CLI command, and build a useful weather watcher.","summary":"Introduces the planned first-project journey and explains Feluqa's command format, including the binary name, command namespace, arguments, and options. It helps readers choose an application profile and follow the setup, CLI structure, first greeting command, and weather-watcher tutorial while clearly separating the planned scaffold from currently available CLI behavior.","weight":1,"tags":["feluqa","getting-started","cli","application"],"date":"2026-10-29T00:00:00.000Z","lastmod":"2026-10-29T00:00:00.000Z","status":"Exploring","draft":true,"author":{"name":"El Moumen Yassine","url":"https://numerimondes.com","linkedin":"https://www.linkedin.com/in/elmoumenyassine","email":"yassine@numerimondes.com"}},"headers":[],"relativePath":"learn/create-your-first-application.md","filePath":"learn/create-your-first-application.md"}`),r={name:"learn/create-your-first-application.md"};function i(s,e,l,c,d,p){return t(),o("div",null,[...e[0]||(e[0]=[n('<blockquote><p><strong>Exploring.</strong> This page describes the intended beginner journey. The interactive project chooser, setup automation in <code>feluqa dev:init</code>, CLI application scaffold, and service packaging described below are not implemented yet. Today, <code>feluqa new &lt;name&gt; --profile web</code> creates the available web application scaffold, and <code>feluqa dev</code> watches and runs a development application.</p></blockquote><p>The first project should answer a useful question from a terminal, then grow into a service that can notify someone when conditions change. The walkthrough will build a weather watcher in small steps so each stage can be run and understood on its own.</p><h2 id="feluqa-command-format" tabindex="-1">Feluqa command format <a class="header-anchor" href="#feluqa-command-format" aria-label="Permalink to &quot;Feluqa command format&quot;">​</a></h2><p>A Feluqa command has a binary name, a command namespace, optional positional arguments, and optional flags or options:</p><div class="language-text vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>&lt;binary&gt; &lt;principal-namespace[:sub-namespace...]&gt; [&lt;argument&gt; ...] [&lt;option&gt; ...]</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><ul><li><strong>Binary</strong> selects the executable, usually <code>feluqa</code>.</li><li><strong>Namespace</strong> names the requested operation. A colon separates nested command namespaces, such as <code>dev:init</code> or <code>support:ide</code>.</li><li><strong>Arguments</strong> provide required values or identify an object, such as <code>zed</code>.</li><li><strong>Options</strong> change the operation or provide named values, such as <code>--profile web</code>; a flag is an option that needs no value.</li></ul><p>For example, <code>feluqa support:ide zed</code> means “run the IDE support command for Zed.” The command routes to its Feluqa handler, which performs validation and the relevant setup work. <code>feluqa dev:init</code> routes to the development setup handler, which selects and prepares the toolchain for the current project.</p><p><strong>This is the target syntax for new namespaced commands.</strong> The current CLI has some space-separated command groups, such as <code>feluqa make resource</code>; those commands have not yet been normalized to the target syntax. The command interface is still being shaped, so the CLI can adopt a consistent namespace form without preserving old command spellings for backward compatibility.</p><h2 id="choose-what-you-are-building" tabindex="-1">Choose what you are building <a class="header-anchor" href="#choose-what-you-are-building" aria-label="Permalink to &quot;Choose what you are building&quot;">​</a></h2><p>The intended <code>feluqa new &lt;name&gt;</code> flow asks what kind of application the project needs:</p><ul><li>a command-line application;</li><li>a server application;</li><li>a workstation application;</li><li>a server and workstation product with separate applications;</li><li>a peer-to-peer application for connected devices.</li></ul><p>The selection should shape the project layout, target profiles, and starter code. A server and workstation solution produces separate applications that can share modules and contracts. They communicate through an explicit API or local protocol; one application does not depend on the other&#39;s executable.</p><h2 id="follow-the-walkthrough" tabindex="-1">Follow the walkthrough <a class="header-anchor" href="#follow-the-walkthrough" aria-label="Permalink to &quot;Follow the walkthrough&quot;">​</a></h2><ol><li><a href="/get-started/installation/">Prepare your development environment</a>: install the Rust toolchain and target dependencies, then choose an editor.</li><li><a href="/get-started/directory-structure/cli-structure">How a Feluqa CLI is structured</a>: learn how the binary, console, profiles, and command handlers fit together.</li><li><a href="/learn/program-0-hello-cli">Program 0: Hello CLI</a>: write a command that prints <code>Hello CLI</code>.</li><li><a href="/learn/build-the-weather-watcher">Build the weather watcher</a>: extend the first command into a useful local service with weather checks and email notifications.</li><li><a href="/get-started/starter-kits/application-profiles-and-starter-kits">Choose an application profile or starter kit</a>: distinguish the selected profile, executable binary, and Rust compilation target.</li></ol>',14)])])}const m=a(r,[["render",i]]);export{u as __pageData,m as default};
